namespace ghidra.app.plugin.core.navigation.locationreferences;

using ghidra.program.database.symbol;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.task;

public class FunctionDefinitionLocationDescriptor : GenericDataTypeLocationDescriptor {

	private FunctionDefinition functionDefinition;

	FunctionDefinitionLocationDescriptor(ProgramLocation location, Program program,
			FunctionDefinition functionDefinition) : base(location, program, functionDefinition)
    {

		this.functionDefinition = functionDefinition;
	}

	/* @Override */
	protected void doGetReferences(Accumulator<LocationReference> accumulator, TaskMonitor monitor)
    {

		findAppliedFunctionDefinition(accumulator);

		ReferenceUtils.findDataTypeReferences(accumulator, functionDefinition, program, true,
			monitor);
	}

	private void findAppliedFunctionDefinition(Accumulator<LocationReference> accumulator) {
		DataType myReturnType = functionDefinition.getReturnType();
		ParameterDefinition[] myParameters = functionDefinition.getArguments();

		FunctionManager functionManager = program.getFunctionManager();
		SymbolTable symbolTable = program.getSymbolTable();
		SymbolIterator symbols = symbolTable.getSymbols(functionDefinition.getName());

		// the definition could be applied in more than one namespace, so handle each application
		while (symbols.hasNext()) {

			Symbol symbol = symbols.next();
			if (!(symbol is FunctionSymbol functionSymbol)) {
				continue;
			}

			long symbolID = functionSymbol.getID();
			Function function = functionManager.getFunction(symbolID);
			FunctionSignature signature = function.getSignature(true);
			ParameterDefinition[] theirParameters = signature.getArguments();
			if (!isSameParamters(myParameters, theirParameters)) {
				continue;
			}

			if (!myReturnType.isEquivalent(signature.getReturnType())) {
				continue;
			}

			ProgramLocation location = symbol.getProgramLocation();
			Address address = symbol.getAddress();
			if (location != null) {
				accumulator.add(new LocationReference(address, null, location));
			}
			else {
				accumulator.add(new LocationReference(address));
			}
		}
	}

	private bool isSameParamters(ParameterDefinition[] myParameters,
			ParameterDefinition[] theirParameters) {
		if (theirParameters.length != myParameters.length) {
			return false;
		}

		for (int i = 0; i < myParameters.length; i++) {
			ParameterDefinition myDefinition = myParameters[i];
			ParameterDefinition theirDefinition = theirParameters[i];
			if (!myDefinition.isEquivalent(theirDefinition)) {
				return false;
			}
		}
		return true;
	}
}
